  "explain": "📖 교재 근거:\n| 천연화장품 | 동식물, 미네랄, 미생물 및 그 유래 원료 등을 함유한 화장품으로, ISO 16128-1 가이드라인에 따라 정의된 천연(유래) 원료를 사용하고, ISO 16128-2 가이드라인에 따라 계산하였을 때 중량 기준으로 천연(유래) 원료 함량이 전체 제품에서 95% 이상으로 구성된 화장품 |\n해설: 천연화장품은 중량 기준으로 천연(유래) 원료 함량이 전체 제품에서 95% 이상으로 구성된 화장품이므로 ⑤번이 옳습니다. 따라서 50%, 70%, 90% 이상으로 제시된 ①·②·③번은 기준 함량에 미치지 못해 틀렸으며, ④번의 유기농 원료 함량 10% 이상 기준은 유기농화장품에 대한 설명입니다.",
