  "explain": "📖 교재 근거:\n| 3년 이하 징역 또는 3천만 원 이하 벌금 (징역형과 벌금형 함께 부과 가능) | • 화장품제조업 또는 화장품책임판매업에 필요한 등록과 변경사항 등록을 위반한 자<br>• 맞춤형화장품판매업에 필요한 신고와 변경사항 신고를 위반한 자<br>• 맞춤형화장품조제관리사를 두지 않은 맞춤형화장품판매업자<br>• 기능성화장품에 대한 심사나 보고서 제출, 이에 대한 변경을 위반한 자<br>• 영업금지 조항을 위반한 자<br>• 등록하지 않은 자가 제조한 화장품 또는 제조·수입하여 유통·판매한 자<br>• 화장품 포장 및 기재·표시사항을 훼손(맞춤형화장품 판매를 위하여 필요한 경우 제외), 위·변조한 자 |\n해설: 근거 구절에 따르면 법령상 등록 및 신고 등의 규율 대상이 되는 영업자에는 화장품제조업자, 화장품책임판매업자, 맞춤형화장품판매업자가 해당하므로 ①, ③, ④, ⑤는 표시 대상 영업자에 속합니다. 반면 ② 원료공급업자는 이러한 화장품 영업자에 해당하지 않으므로 포장에 상호 및 주소를 기재해야 하는 영업자가 아닙니다.",
