  "explain": "📖 법령 근거 (L921):\n| 1년 이하 징역 또는 1천만 원 이하 벌금 (징역형과 벌금형 함께 부과 가능) | • 영유아 또는 어린이 사용 화장품임을 표시·광고하기 위한 안전과 품질 입증 자료 작성·보관을 위반한 자<br>• 안전용기·포장의 기준을 위반한 자<br>• 의약품으로 잘못 인식할 수 있게 표시 또는 광고를 한 자<br>• 기능성화장품으로 잘못 인식할 수 있거나 안전성·유효성 심사 결과와 다른 내용의 표시·광고를 한 자<br>• 소비자를 속이거나 소비자가 잘못 인식하도록 할 우려가 있는 표시·광고를 하거나 판매한 자<br>• 화장품의 기재사항, 가격표시, 기재·표시상의 주의를 위반한 화장품 또는 의약품으로 잘못 인식할 수 있게 기재·표시된 화장품을 판매한 자<br>• 판매 목적이 아닌 제품의 홍보·판매 촉진 등을 위해 미리 소비자가 시험·사용하도록 제조 또는 수입된 화장품을 판매하거나 판매할 목적으로 보관·진열한 자<br>• 화장품의 용기에 담은 내용물을 나누어 판매한 자(단, 맞춤형화장품조제관리사를 통해 판매하는 맞춤형화장품판매업자는 제외)<br>• 실증 자료 제출 요청을 받고도 제출하지 않은 채 계속 표시·광고를 하여 내린 중지명령을 따르지 않은 자 |\n해설: 화장품의 실증 자료 제출 요청을 받고도 제출하지 않은 채 계속 표시·광고를 하여 내린 중지명령을 따르지 않은 자에 대한 처벌 기준은 '1년 이하의 징역 또는 1천만 원 이하의 벌금'에 해당하므로 정답은 ④입니다. 따라서 5년 이하의 징역(①), 2년 이하의 징역(②), 3년 이하의 징역(③), 300만 원 이하의 벌금(⑤)을 규정한 선지들은 모두 옳지 않습니다.",
