  "explain": "📖 교재 근거:\n• 원료업체의 원료에 대한 자가품질검사 시험성적서 중 대한화장품협회의 '원료공급자의 검사결과 신뢰 기준 자율규약' 기준에 적합한 것\n해설: 화장품 성분 명칭은 식약처장이 고시하거나 대한화장품협회에서 발행한 화장품 성분 사전에 등록된 표준화된 한글 명칭으로 표기해야 하므로 ④가 옳습니다. 따라서 임의의 영문 약어나 화학 결합 기호, 한자·라틴어를 사용하거나 번호로 대체하는 표기(①, ②, ③, ⑤)는 올바르지 않습니다.",
