  "derivedFrom": "subject1_q38#1",
  "explain": "📖 교재 근거:\n「소비자기본법」 소비자단체 또는 대통령령으로 정하는 일정 수 이상의 소비자('소비자 등')는 요건을 갖추어 식약처장에게 위해성 평가를 요청할 수 있다.\n해설: 소비자의 피해 구제 및 분쟁 해결 기준의 기본 근거가 되는 법률은 「소비자기본법」(및 소비자분쟁해결기준)이므로 ①번이 정답입니다. 약사법, 화장품법, 민법, 독점규제 및 공정거래에 관한 법률 등은 해당 분쟁 해결 및 반품·환불 기준의 기본 근거 법률에 해당하지 않습니다.",
