  "explain": "📖 교재 근거:\n| 50만 원 | • 화장품의 생산실적 또는 수입실적 또는 화장품 원료의 목록 등을 보고하지 않은 자<br>• 맞춤형화장품 원료의 목록을 보고하지 않은 자<br>• 책임판매관리자 및 맞춤형화장품조제관리사가 매년 화장품의 안전성 확보 및 품질관리에 관한 교육을 받지 않는 경우<br>• 식품의약품안전처장이 필요 시 영업자에게 화장품 관련 법령 및 제도에 관한 교육을 명할 시 그 명령을 위반한 자<br>• 폐업신고를 하지 않은 자<br>• 화장품의 판매가격을 표시하지 않은 자 |\n해설: 소비자의 기호 변화로 수요가 감소한 경우(②)는 화장품 회수 사유에 해당하지 않으므로 정답입니다. 반면 위해화장품 판명, 유통기한 경과, 표시·광고 기준 위반, 품질관리기준 부적합(①, ③, ④, ⑤)은 회수 사유에 해당하므로 오답입니다.",
