  "explain": "📖 교재 근거:\n| 유기농화장품 🎯 기출 | 유기농 원료, 동식물, 미네랄, 미생물 및 그 유래 원료 등을 함유한 화장품으로, ISO 16128-1 가이드라인에 따라 정의된 천연(유래) 및 유기농(유래) 원료를 사용하고, ISO 16128-2 가이드라인에 따라 계산하였을 때 중량 기준으로 유기농(유래) 함량이 전체 제품에서 10% 이상이어야 하며, 유기농(유래) 함량을 포함한 천연(유래) 함량이 전체 제품에서 95% 이상으로 구성된 화장품 |\n해설: 화장품법상 유기농화장품은 천연(유래) 및 유기농(유래) 원료를 사용하고, 중량 기준으로 유기농(유래) 함량이 전체 제품에서 10% 이상이며 유기농(유래) 함량을 포함한 천연(유래) 함량이 95% 이상으로 구성된 화장품이므로 ②가 정답입니다. 따라서 유기농 원료 50% 이상(①), 모든 원료의 인증(③), 원료 미사용(④), ISO 22716 인증(⑤)을 제시한 선지들은 규정된 정의와 맞지 않아 오답입니다.",
  "tags": [
   "정답판정",
   "수치",
   "정의"
  ],
  "source": "화장품법의 이해 (140제)"
