  "sid": "law_st_3ecf08",
  "derivedFrom": "subject1_q62#1",
  "explain": "📖 교재 근거:\n| 화장품 제조업 | 화장품의 전부 또는 일부를 제조(2차 포장 또는 표시만의 공정은 제외)하는 영업<br>• 화장품을 직접 제조하는 영업<br>• 화장품 제조를 위탁받아 제조하는 영업<br>• 화장품을 포장(1차 포장만 해당)하는 영업 |\n해설: 화장품법상 화장품제조업과 화장품책임판매업은 등록 대상이며, 맞춤형화장품판매업은 신고 대상이므로 바르게 연결된 것은 ①번입니다. 따라서 각 영업의 구분을 허가나 신고, 등록 등으로 잘못 연결한 ②, ③, ④, ⑤번은 오답입니다.",
