  "explain": "📖 교재 근거:\n민감정보와 고유식별정보 처리는 개인정보 처리 동의 외 별도의 동의를 받은 경우, 법령에서 허용하는 경우를 제외하고는 처리가 제한되며, 개인정보처리자는 정보가 분실·유출되지 않도록 안전성을 확보해야 한다.\n해설: 민감정보와 고유식별정보 처리는 개인정보 처리 동의 외에 별도의 동의를 받은 경우 또는 법령에서 허용하는 경우를 제외하고는 처리가 제한된다. 따라서 일반 개인정보 처리 동의 외에 별도의 동의가 필요하다.",
